const req = $('Clean Up Request').first().json;
const resp = $('Apollo - Search People').first().json || {};
const people = resp.people || [];

// Everyone already in the Google Sheet is skipped - whatever their status
// (approved, rejected, do_not_contact...). Nobody is enriched or emailed twice.
const known = new Set();
for (const r of $('Load Known Prospects').all()) {
  const id = (r.json || {}).apolloId;
  if (id) known.add(String(id));
}

// Free pre-score on title only, so Apollo credits go to the best people first.
function preScore(title) {
  const t = String(title || '').toLowerCase();
  if (/(owner|founder|ceo|managing director|president|chief)/.test(t)) return 3;
  if (/(director|head of|vp|vice president)/.test(t)) return 2;
  if (/manager/.test(t)) return 1;
  return 0;
}

const fresh = people.filter(p => p && p.id && !known.has(String(p.id)));
fresh.sort((x, y) => preScore(y.title) - preScore(x.title));
const pick = fresh.slice(0, req.maxToEnrich);

const stats = { found: Number(resp.total_entries || people.length), returned: people.length, alreadyKnown: people.length - fresh.length };

if (!pick.length) {
  return [{ json: Object.assign({ ids: [] }, stats) }];
}

// Bulk enrichment takes up to 10 people per call.
const out = [];
for (let i = 0; i < pick.length; i += 10) {
  out.push({ json: Object.assign({ ids: pick.slice(i, i + 10).map(p => p.id) }, stats) });
}
return out;

