const req = $('Clean Up Request').first().json;
const titlesWanted = req.jobTitles.map(s => s.toLowerCase());
const industryWanted = String(req.industryKeywords || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const out = [];

for (const item of $input.all()) {
  for (const p of (item.json.matches || [])) {
    if (!p || !p.id) continue;
    const org = p.organization || {};
    const title = String(p.title || '');
    const t = title.toLowerCase();
    const email = String(p.email || '');
    const emailStatus = String(p.email_status || '').toLowerCase();
    const hasVerifiedEmail = Boolean(email) && emailStatus === 'verified';
    const employees = Number(org.estimated_num_employees || 0);
    const industry = String(org.industry || '');
    const website = org.website_url || (org.primary_domain ? 'https://' + org.primary_domain : '');

    // ---- Fixed scoring rules - no AI ----
    let score = 0;
    const reasons = [];

    if (/(owner|founder|ceo|managing director|president|chief)/.test(t)) { score += 35; reasons.push('Decision maker'); }
    else if (/(director|head of|vp|vice president)/.test(t)) { score += 25; reasons.push('Senior leader'); }
    else if (/manager/.test(t)) { score += 12; reasons.push('Manager'); }
    else { reasons.push('Junior or unclear title'); }

    if (titlesWanted.some(k => t.includes(k))) { score += 15; reasons.push('Title matches campaign'); }

    if (hasVerifiedEmail) { score += 20; reasons.push('Verified email'); }
    else { reasons.push('No verified email'); }

    if (employees > 0 && employees >= req.minEmployees && employees <= req.maxEmployees) { score += 15; reasons.push('Company size in range'); }
    else if (employees > 0) { reasons.push('Company size outside range'); }
    else { reasons.push('Company size unknown'); }

    if (industryWanted.length && industryWanted.some(k => industry.toLowerCase().includes(k))) { score += 10; reasons.push('Industry match'); }

    if (website) { score += 5; reasons.push('Has website'); }

    if (score > 100) score = 100;

    out.push({ json: {
      apolloId: String(p.id),
      campaign: req.campaignName,
      firstName: p.first_name || '',
      lastName: p.last_name || '',
      fullName: p.name || [p.first_name, p.last_name].filter(Boolean).join(' '),
      title: title,
      email: email,
      emailStatus: emailStatus,
      hasVerifiedEmail: hasVerifiedEmail,
      linkedinUrl: p.linkedin_url || '',
      city: p.city || '',
      country: p.country || '',
      company: org.name || '',
      website: website,
      industry: industry,
      employees: employees,
      score: score,
      reasons: reasons
    }});
  }
}
return out;

const lead = $('Flatten & Score Leads').item.json;
const raw = typeof $json.data === 'string' ? $json.data : '';
const text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 3000);
return { json: Object.assign({}, lead, { websiteText: text, websiteRead: text.length > 200 }) };

