const lead = Object.assign({}, $('Prepare Website Text').item.json);
delete lead.websiteText;
const ai = ($json && $json.output) || {};
const reasons = (lead.reasons || []).slice();

// Status is decided by rules. Only strong, emailable prospects reach the review queue.
let status = 'pending_review';
if (!lead.hasVerifiedEmail) { status = 'low_fit'; reasons.push('Held back: no verified email'); }
else if (lead.score < 60) { status = 'low_fit'; reasons.push('Score below 60'); }

if (!ai.emailBody) reasons.push('No AI draft - write manually');
if (ai.usedWebsite === false) reasons.push('Website not used for personalisation');

return { json: Object.assign(lead, {
  reasons: reasons.join(', '),
  companySummary: ai.companySummary || '',
  relevantHook: ai.relevantHook || '',
  subjectLine: ai.subjectLine || '',
  emailBody: ai.emailBody || '',
  aiConfidence: Number(ai.confidence || 0),
  senderName: $('Clean Up Request').first().json.senderName,
  status: status
}) };

const rows = $('Set Final Status').all().map(i => i.json);
const review = rows.filter(r => r.status === 'pending_review').sort((x, y) => y.score - x.score);
const lines = review.slice(0, 15).map(r => '- *' + r.fullName + '* - ' + r.title + ', ' + r.company + ' (' + r.score + '/100)');
if (review.length > 15) lines.push('...and ' + (review.length - 15) + ' more in the sheet');
return [{ json: {
  campaign: $('Clean Up Request').first().json.campaignName,
  total: rows.length,
  reviewCount: review.length,
  lowFitCount: rows.length - review.length,
  lines: lines.join('\n') || 'None this time.'
}}];

